cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cuda_pipeline.h>
#include <cute/tensor.hpp>
using namespace cute;
// Tiled GEMM kernel using CUTE tensors for global memory addressing
// Block computes a BM x BN tile of C, with BK reduction step per iteration.
// Each thread computes a TM x TN sub-tile stored in registers.
// Global->shared staging uses cp.async (via __pipeline_memcpy_async) so that
// the async copy engine overlaps data movement with the compute for the
// previous K-slab instead of round-tripping through registers.
constexpr int BM = 128;
constexpr int BN = 128;
constexpr int BK = 8;
constexpr int TM = 8;
constexpr int TN = 8;
// blockDim = (BN/TN, BM/TM) = (16, 16) -> 256 threads
constexpr int WARPS_M = 2;
constexpr int WARPS_N = 4;
constexpr int WM = BM / WARPS_M; // 64
constexpr int WN = BN / WARPS_N; // 32
constexpr int LANE_ROWS = WM / TM; // 8
constexpr int LANE_COLS = WN / TN; // 4
constexpr int SWZ_CHUNK = 32;
constexpr int SWZ_PAD = 4;
constexpr int BM_PAD = BM + (BM / SWZ_CHUNK) * SWZ_PAD;
__device__ __forceinline__ int swz_m(int m) {
    return m + (m / SWZ_CHUNK) * SWZ_PAD;
}
__global__ void cute_gemm_kernel(
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C,
    int M, int N, int K)
{
    __shared__ float sA[3][BK][BM_PAD];
    __shared__ float sA_raw[3][BM][BK];
    __shared__ float sB[3][BK][BN];
    // CUTE tensor describing the global output matrix (row-major)
    Tensor gC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));
    int tid = threadIdx.x; // 0..255 linear thread index within block
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    int warp_row = warp_id / WARPS_N;
    int warp_col = warp_id % WARPS_N;
    int lane_row = lane_id / LANE_COLS;
    int lane_col = lane_id % LANE_COLS;
    int bx = blockIdx.x;
    int by = blockIdx.y;
    int row0 = by * BM;
    int col0 = bx * BN;
    // Warp-level tiling: each warp owns a WM x WN sub-tile of the block tile,
    // and each lane within the warp owns a TM x TN register tile, arranged so
    // that consecutive lanes read consecutive shared-memory columns (B) and
    // broadcast-friendly rows (A), improving locality and reducing conflicts.
    int row_in_block = warp_row * WM + lane_row * TM;
    int col_in_block = warp_col * WN + lane_col * TN;
    int row_in_block_s = swz_m(row_in_block);
    // Each thread loads exactly one float4 for A tile and one float4 for B tile per K-slab
    int rA = tid / (BK / 4);
    int cA4 = tid % (BK / 4);
    int cA = cA4 * 4;
    int gr_a = row0 + rA;
    int rA_s = swz_m(rA);
    int rB = tid / (BN / 4);
    int cB4 = tid % (BN / 4);
    int cB = cB4 * 4;
    int gc_b = col0 + cB;
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.f;
        }
    }
    // Asynchronously stage a K-slab of A and B into shared memory. A is copied
    // with a single fully-coalesced 16-byte cp.async into a scratch buffer that
    // mirrors the contiguous row-major global layout (the transposed destination
    // needed for compute cannot itself be expressed as one contiguous copy). B is
    // both source- and destination-contiguous, so it uses a single 16-byte copy
    // straight into its final shared location as before.
    auto load_slab_async = [&](int buf, int k0) {
        bool a_valid = (gr_a < M) && (k0 + cA + 3 < K);
        if (a_valid) {
            const float* a_src = &A[gr_a * K + (k0 + cA)];
            __pipeline_memcpy_async(&sA_raw[buf][rA][cA], a_src, sizeof(float4));
        } else {
            sA_raw[buf][rA][cA + 0] = (gr_a < M && k0 + cA + 0 < K) ? A[gr_a * K + k0 + cA + 0] : 0.f;
            sA_raw[buf][rA][cA + 1] = (gr_a < M && k0 + cA + 1 < K) ? A[gr_a * K + k0 + cA + 1] : 0.f;
            sA_raw[buf][rA][cA + 2] = (gr_a < M && k0 + cA + 2 < K) ? A[gr_a * K + k0 + cA + 2] : 0.f;
            sA_raw[buf][rA][cA + 3] = (gr_a < M && k0 + cA + 3 < K) ? A[gr_a * K + k0 + cA + 3] : 0.f;
        }
        bool b_valid = (k0 + rB < K) && (gc_b + 3 < N);
        if (b_valid) {
            const float* b_src = &B[(k0 + rB) * N + gc_b];
            __pipeline_memcpy_async(&sB[buf][rB][cB], b_src, sizeof(float4));
        } else {
            float4 v;
            v.x = (k0 + rB < K && gc_b + 0 < N) ? B[(k0 + rB) * N + gc_b + 0] : 0.f;
            v.y = (k0 + rB < K && gc_b + 1 < N) ? B[(k0 + rB) * N + gc_b + 1] : 0.f;
            v.z = (k0 + rB < K && gc_b + 2 < N) ? B[(k0 + rB) * N + gc_b + 2] : 0.f;
            v.w = (k0 + rB < K && gc_b + 3 < N) ? B[(k0 + rB) * N + gc_b + 3] : 0.f;
            *reinterpret_cast<float4*>(&sB[buf][rB][cB]) = v;
        }
    };
    // Transpose the raw A scratch tile into the swizzled shared layout consumed
    // by the compute loop. This is a cheap shared-memory-to-shared-memory copy
    // done once per K-slab (by the same thread that wrote the scratch data),
    // performed only after that slab's async copy has been confirmed complete.
    auto transpose_slab = [&](int buf) {
        #pragma unroll
        for (int i = 0; i < 4; ++i) {
            sA[buf][cA + i][rA_s] = sA_raw[buf][rA][cA + i];
        }
    };
    constexpr int STAGES = 3;
    // Prime the pipeline: prefetch the first two K-slabs (stages 0 and 1)
    // so that, once compute begins, a third slab can already be in flight,
    // giving the async copy engine two full slabs of lead time to overlap
    // with compute instead of just one.
    load_slab_async(0, 0);
    __pipeline_commit();
    bool has_stage1 = (BK < K);
    if (has_stage1) {
        load_slab_async(1, BK);
        __pipeline_commit();
    }
    __pipeline_wait_prior(has_stage1 ? 1 : 0);
    transpose_slab(0);
    __syncthreads();
    for (int it = 0; it * BK < K; ++it) {
        int cur = it % STAGES;
        int nxt2_idx = it + (STAGES - 1);
        bool has_next2 = (nxt2_idx * BK < K);
        if (has_next2) {
            int nxt2 = nxt2_idx % STAGES;
            // Issue the async copy two stages ahead; it proceeds concurrently
            // with the compute below that consumes the current slab, giving
            // extra lead time versus a simple double-buffered pipeline.
            load_slab_async(nxt2, nxt2_idx * BK);
            __pipeline_commit();
        }
        // Compute: register-blocked outer product over the BK reduction dim
        // (overlapped with the async prefetch issued above)
        #pragma unroll
        for (int kk = 0; kk < BK; ++kk) {
            float4 a_reg4_0 = *reinterpret_cast<const float4*>(&sA[cur][kk][row_in_block_s]);
            float4 a_reg4_1 = *reinterpret_cast<const float4*>(&sA[cur][kk][row_in_block_s + 4]);
            float a_reg[TM] = {a_reg4_0.x, a_reg4_0.y, a_reg4_0.z, a_reg4_0.w,
                                a_reg4_1.x, a_reg4_1.y, a_reg4_1.z, a_reg4_1.w};
            float4 b_reg4_0 = *reinterpret_cast<const float4*>(&sB[cur][kk][col_in_block]);
            float4 b_reg4_1 = *reinterpret_cast<const float4*>(&sB[cur][kk][col_in_block + 4]);
            float b_reg[TN] = {b_reg4_0.x, b_reg4_0.y, b_reg4_0.z, b_reg4_0.w,
                                b_reg4_1.x, b_reg4_1.y, b_reg4_1.z, b_reg4_1.w};
            #pragma unroll
            for (int i = 0; i < TM; ++i) {
                #pragma unroll
                for (int j = 0; j < TN; ++j) {
                    acc[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }
        bool has_next = ((it + 1) * BK < K);
        if (has_next) {
            __pipeline_wait_prior(has_next2 ? 1 : 0);
            transpose_slab((it + 1) % STAGES);
        }
        __syncthreads();
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        int gr = row0 + row_in_block + i;
        if (gr >= M) continue;
        int gc0 = col0 + col_in_block;
        float* c_row = &C[(size_t)gr * N + gc0];
        bool vec_ok = (gc0 + 7 < N) && (((size_t)gr * (size_t)N + (size_t)gc0) % 4 == 0);
        if (vec_ok) {
            float4 v0 = make_float4(acc[i][0], acc[i][1], acc[i][2], acc[i][3]);
            float4 v1 = make_float4(acc[i][4], acc[i][5], acc[i][6], acc[i][7]);
            *reinterpret_cast<float4*>(c_row + 0) = v0;
            *reinterpret_cast<float4*>(c_row + 4) = v1;
        } else {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                int gc = gc0 + j;
                if (gc < N) {
                    c_row[j] = acc[i][j];
                }
            }
        }
    }
}
torch::Tensor cute_gemm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
